css.rules:
.icon { display: block; }
.icon svg { width: inherit; height: inherit; display: block; color: currentcolor; pointer-events: none; }
.icon svg * { fill: currentcolor; }

.playback-controls-play { width: var(--playback-control-button-width, 32px); height: var(--playback-control-button-height, 32px); display: flex; flex: 0 0 auto; align-items: stretch; justify-content: stretch; position: relative; }
.playback-controls-play button { width: 100%; height: 100%; position: relative; transition: color 0.2s ease-out; }
.playback-controls-play amp-icon { width: var(--playback-control-icon-width, 32px); height: var(--playback-control-icon-height, 28px); display: block; position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); }
button.playback-play__play, button.playback-play__pause, button.playback-play__stop { transition: transform 0.2s ease-out; margin: 0px; padding: 0px; display: inline-block; border: 0px; background-color: transparent; outline: none; cursor: pointer; appearance: none; font-family: inherit; font-size: inherit; line-height: inherit; width: 100%; height: 100%; position: absolute; top: 0px; left: 0px; color: var(--playback-controls-play-color, #fff); }
button.playback-play__play:enabled:active, button.playback-play__pause:enabled:active, button.playback-play__stop:enabled:active { transform: scale(0.9); }
button.playback-play__play:enabled:active::before, button.playback-play__pause:enabled:active::before, button.playback-play__stop:enabled:active::before { width: 38px; height: 38px; opacity: 0.2; }
button.playback-play__play::before, button.playback-play__pause::before, button.playback-play__stop::before { content: ""; width: 32px; height: 32px; display: block; position: absolute; z-index: -1; top: 50%; left: 50%; transform: translate(-50%, -50%); border-radius: 50%; background: rgb(0, 0, 0); transition: opacity 0.2s ease-out; opacity: 0; }
@media (prefers-color-scheme: dark) {
  button.playback-play__play::before, button.playback-play__pause::before, button.playback-play__stop::before { background: rgb(255, 255, 255); }
}
button.playback-play__play:hover:not([disabled]), button.playback-play__play:focus-visible:not([disabled]), button.playback-play__pause:hover:not([disabled]), button.playback-play__pause:focus-visible:not([disabled]), button.playback-play__stop:hover:not([disabled]), button.playback-play__stop:focus-visible:not([disabled]) { color: var(--playback-controls-play-color-hover, var(--playback-controls-play-color, #fff)); }
button.playback-play__play:focus-visible, button.playback-play__pause:focus-visible, button.playback-play__stop:focus-visible { --sk-focus-offset: 2px; outline: 4px solid var(--sk-focus-color, var(--keyColor-focus-color, var(--keyColor, #0071e3))); outline-offset: var(--sk-focus-offset, 1px); }
button.playback-play__play[aria-hidden="true"], button.playback-play__pause[aria-hidden="true"], button.playback-play__stop[aria-hidden="true"] { opacity: 0; pointer-events: none; }
button.playback-play__play:disabled, button.playback-play__pause:disabled, button.playback-play__stop:disabled { opacity: 0.4; cursor: default; }
.button__label { position: absolute; clip: rect(1px, 1px, 1px, 1px); clip-path: inset(0px 0px 99.9% 99.9%); overflow: hidden; height: 1px; width: 1px; padding: 0px; border: 0px; }

html { text-size-adjust: 100%; box-sizing: border-box; }
abbr, blockquote, body, button, dd, dl, dt, fieldset, figure, form, h1, h2, h3, h4, h5, h6, hgroup, input, legend, li, ol, p, pre, ul { margin: 0px; padding: 0px; }
address, caption, code, figcaption, pre, th { font-size: 1em; font-style: normal; font-weight: 400; }
fieldset, iframe { border: 0px; }
caption, th { text-align: start; }
table { border-collapse: collapse; border-spacing: 0px; }
audio, canvas, progress, video { vertical-align: baseline; }
button { background: none; border: 0px; color: inherit; cursor: pointer; font: inherit; vertical-align: inherit; }
button:disabled { cursor: default; }
*, ::after, ::before { box-sizing: inherit; }
a, blockquote, body, code, dd, div, dl, dt, embed, fieldset, footer, form, h1, h2, h3, h4, h5, h6, header, html, img, legend, li, ol, p, pre, section, table, td, th, ul { user-select: none; -webkit-user-drag: none; }
[contenteditable] { user-select: auto !important; }
ul { list-style-type: none; }
svg { pointer-events: none; }
